import React from 'react'
import Pasta from '../../assets/images/pasta.avif';

function Section1() {
  return (
    <section className="hero_section">

      {/* MARQUEE */}
      <div className="hero_marquee_container">
        <div className="marquee_track">
          <h1>L'EREDITÀ L'EREDITÀ L'EREDITÀ</h1>
          <h1>L'EREDITÀ L'EREDITÀ L'EREDITÀ</h1>
        </div>
      </div>

      {/* PASTA */}
      <div className="pasta_overlay">
        <img src={Pasta} alt="Pasta Fork" />
      </div>

      {/* TEXT */}
      <div className="hero_text text-end text-white">
        <h2>
          PERIGOSAMENTE DELICIOSO, TÃO BOM QUE NOSSOS PRATOS ATÊ FALAM ITALIANO.
        </h2>
      </div>

    </section>
  )
}

export default Section1;
